import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;

public class DateTimeService {
    private static final DateTimeFormatter ISO_FORMATTER = DateTimeFormatter.ISO_ZONED_DATE_TIME;

    public void processTemporalData() {
        Instant nowInstant = Instant.now();

        ZonedDateTime systemZoned = nowInstant.atZone(ZoneId.of("America/New_York"));

        LocalDate today = systemZoned.toLocalDate();
        LocalDate futureDate = today.plus(Period.ofDays(14));

        Duration executionTime = Duration.between(nowInstant, Instant.now().plus(150, ChronoUnit.MILLIS));

        String formatted = systemZoned.format(ISO_FORMATTER);
        ZonedDateTime parsed = ZonedDateTime.parse(formatted, ISO_FORMATTER);

        System.out.println("Parsed Date: " + parsed);
        System.out.println("Execution Duration (ms): " + executionTime.toMillis());
    }
}
